app.post('/c/incidents/:id/followup', (req, res) => {
  if (!canWrite()) return res.status(403).end();
  const id = Number(req.params.id);
  const inc = incQ.one.get(id);
  if (!inc) return res.status(404).end();
  const clean = (v) => (String(v == null ? '' : v).trim() || null);
  const newStatus = INC_STATUSES.includes(req.body.new_status) ? req.body.new_status : null;
  const newAssigned = clean(req.body.new_assigned);
  const newDue = clean(req.body.new_due);
  const note = clean(req.body.note);
  if (!note && !newStatus && !newAssigned && !newDue) return res.redirect(`/c/incidents/${id}`);
  incQ.addEvent.run({ incident_id: id, actor: incWho(req), note, new_status: newStatus, new_assigned: newAssigned, new_due: newDue });
  const sets = [], vals = { id };
  if (newStatus) { sets.push('status=@status'); vals.status = newStatus; }
  if (newAssigned) { sets.push('assigned_to=@assigned'); vals.assigned = newAssigned; }
  if (newDue) { sets.push('follow_up_due=@due'); vals.due = newDue; }
  if (sets.length) db.prepare(`UPDATE m_incidents SET ${sets.join(', ')} WHERE id=@id`).run(vals);
  res.redirect(`/c/incidents/${id}?msg=` + encodeURIComponent('Follow-up added.'));
});

mountModules(app, csrfBody);

// ---------------------------------------------------------------------------
// One-time data migration: the two months of history that pre-date ZWIN.
//
// It runs at boot because there is no other way in — the database lives on a
// Render disk with no shell. It is guarded three ways: a marker so it never
// runs twice, a date check so it never touches a service that already exists,
// and one transaction so a failure leaves nothing behind.
//
// It must never stop the app starting. A missing backfill is a thing you
// notice and re-run; a server that will not boot is an outage.
//
// Skipped under test, where every file gets an empty database and seventy-two
// services appearing in it would be seventy-two services nobody asked for.
// ---------------------------------------------------------------------------
if (process.env.ZWIN_SKIP_BACKFILL !== '1') {
  try {
    const BACKFILL = require('./backfill');
    // A one-row correction that has to reach databases the backfill already
    // ran on. Idempotent and outside the marker, so it applies once and then
    // finds nothing to do.
    const fixed = BACKFILL.fixJul11Wages();
    if (fixed.length) console.log(`\n  Backfill: corrected 11 Jul rates — ${fixed.join(', ')}.`);
    const out = BACKFILL.run();
    if (out.ran) {
      const r = out.report;
      console.log(`\n  Backfill: ${r.inserted.length} services imported, ${r.staff} staff rows, ${r.servers} server-sales rows.`);
      if (r.created.length) console.log(`  Backfill: created ${[...new Set(r.created)].join(', ')}.`);
      if (r.matched.length) console.log(`  Backfill: matched ${[...new Set(r.matched)].join('; ')}.`);
      if (r.skipped.length) console.log(`  Backfill: skipped ${r.skipped.length} (${r.skipped.map((x) => x.date).join(', ')}).`);
    }
  } catch (e) {
    console.error('\n  Backfill FAILED and was rolled back. The app is running without it.');
    console.error('  ' + (e && e.message ? e.message : e) + '\n');
  }
}

// ---------------------------------------------------------------------------
// DAILY BACK-OFFICE SWEEP
// ---------------------------------------------------------------------------
// Four of the admin notifications have no moment to hang off — nothing happens
// the day an invoice tips into overdue, or a pay period closes unsent, or a
// document's renewal creeps within two weeks. So a light pass runs once a day
// and raises them. Every alert goes through PORTAL.adminNotifyOnce with a stable
// key, so a situation is announced once and never re-nagged the next morning.
const daysUntil = (d) => (d ? Math.round((new Date(d + 'T00:00:00') - startOfToday()) / 86400000) : null);

function runAdminSweep() {
  const docsDated = db.prepare(
    'SELECT id, title, category, expires_on, action_by FROM m_documents WHERE expires_on IS NOT NULL OR action_by IS NOT NULL');

  // #8 — a pay period ended and nothing (send or skip) has gone out.
  try {
    const justEnded = recentPeriods(2)[1];
    if (justEnded && justEnded.end < isoDate(startOfToday())
        && !sendRecord(justEnded.start) && !skipRecord(justEnded.start)) {
      PORTAL.adminNotifyOnce(`period_unsent:${justEnded.start}`, 'payroll',
        `Payroll not sent — ${labelFor(justEnded)}`,
        { body: 'The pay period has ended and nothing has gone out yet.', href: '/payroll' });
    }
  } catch (e) { console.error('[sweep] payroll', e && e.message); }

  // #15 — an open invoice due today or past due.
  try {
    for (const inv of dashQ.openInvoices.all()) {
      const st = invStatus(inv);
      const overdue = st.key === 'overdue';
      if (!overdue && st.label !== 'Due today') continue;
      const vn = inv.vendor_id ? (invQ.vendors.all().find((v) => Number(v.id) === Number(inv.vendor_id)) || {}).name : null;
      PORTAL.adminNotifyOnce(`inv:${inv.id}:${overdue ? 'overdue' : 'due'}`, 'invoice',
        overdue ? `Invoice overdue — ${vn || 'a vendor'}` : `Invoice due today — ${vn || 'a vendor'}`,
        { body: `${inv.invoice_number ? '#' + inv.invoice_number + ' · ' : ''}${money(inv.amount_cents || 0)} · ${st.label}`,
          href: `/c/invoices#inv-${inv.id}` });
    }
  } catch (e) { console.error('[sweep] invoices', e && e.message); }

  // #25 — a floor / out-of-stock report left open more than a day.
  try {
    for (const r of PORTAL.q.stockOpen.all()) {
      const ageMs = Date.now() - new Date(String(r.reported_at).replace(' ', 'T') + 'Z').getTime();
      if (!(ageMs >= 24 * 3600000)) continue;
      PORTAL.adminNotifyOnce(`floor_stale:${r.id}`, 'floor', `Still out: ${r.item}`,
        { body: `${r.reported_by || 'Someone'} reported it ${atTime(r.reported_at)} — not cleared yet`,
          href: '/staff-portal' });
    }
  } catch (e) { console.error('[sweep] floor', e && e.message); }

  // #29 — a document's renewal or action deadline within 30 / 14 / 0 days.
  try {
    for (const d of docsDated.all()) {
      for (const [field, verb] of [['expires_on', 'expires'], ['action_by', 'due']]) {
        const on = d[field];
        if (!on) continue;
        const days = daysUntil(on);
        if (days == null) continue;
        const step = days <= 0 ? 0 : days <= 14 ? 14 : days <= 30 ? 30 : null;
        if (step == null) continue;
        const when = days < 0 ? `${verb === 'expires' ? 'expired' : 'was due'} ${-days} day${days === -1 ? '' : 's'} ago`
          : days === 0 ? `${verb} today` : `${verb} in ${days} day${days === 1 ? '' : 's'}`;
        PORTAL.adminNotifyOnce(`doc:${d.id}:${field}:${step}`, 'document',
          `${d.title || d.category || 'A document'} ${when}`,
          { body: `${d.category ? d.category + ' · ' : ''}${niceDate(on)}`, href: `/c/documents/${d.id}` });
      }
    }
  } catch (e) { console.error('[sweep] documents', e && e.message); }
}

/**
 * Tell people their timesheet is waiting to be signed.
 *
 * A pay period ends on a Sunday night and nobody is thinking about it. The
 * submit button is correctly hidden until the period is over, so the one
 * moment it appears is the one moment nobody is looking — and payroll spends
 * Monday chasing signatures by text.
 *
 * Two reminders, and only two. The first the day the period ends; the second
 * two days later if it is still unsigned, because a single notification that
 * lands while a phone is off is not a reminder. A third would be nagging, and
 * a reminder people turn off is worse than none.
 *
 * periodToSign is the same function the portal's own banner uses, so what the
 * notification says and what the page shows can never disagree — including
 * that it stays quiet for anyone with no hours in the period, and for anyone
 * whose sheet is already submitted, approved or locked.
 */
function runStaffSweep() {
  const today = TC.businessDateOf(TC.nowUtc(), TC.settings().cutoffHour);
  for (const emp of q.allEmployees.all()) {
    try {
      const p = periodToSign(emp, today);
      if (!p) continue;
      const v = tsView(emp, p);
      const hrs = TC.hm(v.totals.payable);
      const href = `/portal/timesheet?p=${p.start}`;
      const key = `ts_remind:${emp.id}:${p.start}`;
      // The first one.
      if (PORTAL.notifyOnce(key, 'timesheet', 'Your timesheet is ready to submit',
        { body: `${labelFor(p)} · ${hrs}. Check it and send it to your manager.`,
          employeeId: emp.id, href })) continue;
      // The second, two days after the FIRST WAS SENT — not two days after the
      // period ended. Those are the same date until a deploy, a restart or an
      // outage delays the first, and then measuring from the period would fire
      // both within a day of each other, which is the nagging this avoids.
      const sentAt = PORTAL.notifiedAt(key);
      if (sentAt && isoDate(new Date(sentAt.replace(' ', 'T') + 'Z')) <= addDays(today, -2)) {
        PORTAL.notifyOnce(`ts_remind2:${emp.id}:${p.start}`, 'timesheet',
          'Your timesheet is still unsigned',
          { body: `${labelFor(p)} · ${hrs}. Payroll needs this one.`,
            employeeId: emp.id, href });
      }
    } catch (e) { console.error('[sweep] timesheet reminder', emp.id, e && e.message); }
  }
}

// Run it at most once per calendar day. Kept in memory, not a table: on a
// restart it simply runs again at boot, and adminNotifyOnce makes that a no-op
// for anything already announced.
let lastSweepDay = null;
function maybeRunDailySweep() {
  try {
    const day = isoDate(startOfToday());
    if (day === lastSweepDay) return;
    lastSweepDay = day;
    runAdminSweep();
    runStaffSweep();
  } catch (e) { console.error('[sweep]', e && e.message); }
}

// --- the last word on any request that threw -------------------------------
//
// Registered after every route, which is the only place Express will use it.
// Without one, Express's default handler answers — and its default, unless
// NODE_ENV happens to say "production", is to put the stack trace in the
// response body. That is absolute paths, the shape of the source tree, and
// sometimes the SQL and the values that went into it, handed to whoever made
// the request fail. Nothing here is worth showing a browser: the stack goes to
// the log, where the owner can read it, and the person gets a sentence.
//
// The four arguments are load-bearing. Express identifies an error handler by
// arity, so dropping the unused `next` silently turns this back into ordinary
// middleware that never runs.
app.use((err, req, res, _next) => {                        // eslint-disable-line no-unused-vars
  console.error(`[error] ${req.method} ${req.originalUrl}`, err && (err.stack || err.message || err));
  if (res.headersSent) return;                             // a half-written page cannot be replaced
  // A malformed body or an oversized upload is the caller's problem and Express
  // already says so; anything else is ours and is a 500.
  const st = err && Number(err.status || err.statusCode);
  res.status(st >= 400 && st < 500 ? st : 500);
  // A form post that dies should not also lose the page it was posted from.
  if ((req.get('accept') || '').includes('text/html')) {
    return res.send(layout('Something went wrong',
      `<div class="bs-page"><h1>Something went wrong</h1>
        <p>That did not save. Nothing was changed. Try again — if it keeps happening, the details are in the server log.</p>
        <a class="bs-back" href="/">← Back</a></div>`));
  }
  res.type('text/plain').send('Something went wrong. Nothing was changed.');
});

app.listen(PORT, () => {
  console.log(`\n  ${RESTAURANT} ops running →  http://localhost:${PORT}\n`);
  if (!process.env.GMAIL_USER && !process.env.SMTP_HOST) {
    console.log('  Email: PREVIEW MODE (no mail configured). "Send" writes files to /previews.\n');
  }
  // The daily sweep. Skipped under test (same flag as the backfill) so a spawned
  // server never fires operational alerts into a throwaway database or leaves an
  // interval keeping the process alive. Shortly after boot, then hourly — the
  // hourly tick is only there to catch the date rolling over on a long-running
  // process; the once-a-day guard makes every extra tick a cheap no-op.
  if (process.env.ZWIN_SKIP_BACKFILL !== '1') {
    setTimeout(maybeRunDailySweep, 8000);
    setInterval(maybeRunDailySweep, 60 * 60 * 1000);
  }
  // A test hook: run the sweep once, synchronously, at boot. Lets a test seed
  // the conditions and assert the alerts without waiting on the timer (which is
  // off under the backfill-skip flag tests use anyway).
  if (process.env.ZWIN_SWEEP_NOW === '1') {
    try { runAdminSweep(); } catch (e) { console.error('[sweep] boot', e && e.message); }
    try { runStaffSweep(); } catch (e) { console.error('[sweep] boot staff', e && e.message); }
  }
});

module.exports = app;
